/**
 * src/lib/tools/selectProgramRecommend.ts
 *
 * 国际教育选校选项目工具执行器（chat-pro Tool Loop 调用）
 * 模拟 volunteerRecommend 的方式，通过 xiaofang 的 get-response1-yuning 接口。
 */

const API_URL =
  process.env.VOLUNTEER_API_URL ||
  'https://xiaofang-ai-prod.nx1.applysquare.net/get-response1-yuning/';

const SAAS_ID = process.env.VOLUNTEER_SAAS_ID || '';
const SCENE = 'know_me_mini';

export interface SelectProgramItem {
  num: string;
  name: string;
  tier: '冲' | '稳' | '保' | string;
  link?: string;
  rawText: string;
}

export interface SelectProgramResult {
  aiText: string;
  programs: SelectProgramItem[];
  links: Record<string, string>;
  allData: Record<string, any> | null;
  totalLines: number;
}

export function buildSelectProgramMessage(params: {
  current_school?: string;
  current_major?: string;
  target_country?: string;
  target_major?: string;
  gpa: number;
  apply_degree: string;
  language_test_type: string;
  language_test_grade: number;
  test_type: string;
  test_grade: number;
  target_major_ids?: string;
}): string {
  const { current_school, current_major, target_country, target_major, gpa, apply_degree, language_test_type, language_test_grade, test_type, test_grade } = params;

  let msg = '';
  if (current_school) msg += `${current_school}，`;
  if (current_major) msg += `${current_major}，`;
  msg += `GPA${gpa || 0}，`;
  msg += `${language_test_type === 'toefl' ? '托福' : '雅思'}${language_test_grade || 0}，`;

  if (test_grade > 0) {
    msg += `${(test_type || '').toUpperCase()}${test_grade}，`;
  }

  let degreeStr = '本科';
  if (apply_degree === 'graduate') degreeStr = '硕士';
  if (apply_degree === 'phd') degreeStr = '博士';

  msg += `申请${target_country || ''}${target_major || ''}${degreeStr}`;
  return msg;
}

function parseProgram(text: string, num: string): Omit<SelectProgramItem, 'link'> {
  let name = text.split('，')[0] || text;
  // xiaofang 返回的文本可能类似："1、麻省理工学院-计算机科学，录取概率20%"
  const matchName = text.match(/^[\d、]+(.+?)[，,]/);
  if (matchName) {
    name = matchName[1].trim();
  }

  let tier = '稳';
  if (text.includes('冲刺')) tier = '冲';
  else if (text.includes('保底')) tier = '保';

  return { num, name, tier, rawText: text };
}

export async function runSelectProgramRecommend(params: any, onProgress?: (msg: string) => void): Promise<SelectProgramResult> {
  const userContent = buildSelectProgramMessage(params);

  const apiPayload: Record<string, any> = {
    history_msgs: [{ role: 'user', content: userContent }],
    scene: SCENE,
    stream: true,
    client_id: '0',  // 传0让 xiaofang 用默认档案；如需绑定用户需从外部注入 token
    saas_client_id: '132927', // 知己平台在平方的 saas ID，推荐算法用此定位学校数据库
    env: 'prod',
  };
  if (SAAS_ID) apiPayload.saas_id = SAAS_ID;

  onProgress?.(`→ 调用选校推荐API: "${userContent}"`);

  const apiRes = await fetch(API_URL, {
    method: 'POST',
    headers: {
      'Accept': 'application/json; indent=4',
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(apiPayload),
    cache: 'no-store',
    // @ts-ignore
    duplex: 'half',
  });

  if (!apiRes.ok) {
    const errText = await apiRes.text();
    throw new Error(`API HTTP ${apiRes.status}: ${errText.slice(0, 200)}`);
  }
  if (!apiRes.body) throw new Error('API 无响应 body');

  const reader = apiRes.body.getReader();
  const decoder = new TextDecoder();
  let buffer = '';
  let lineCount = 0;
  let aiText = '';
  const programs: SelectProgramItem[] = [];
  const links: Record<string, string> = {};
  let allData: Record<string, any> | null = null;

  while (true) {
    const { value, done } = await reader.read();
    if (done) break;

    buffer += decoder.decode(value, { stream: true });
    const lines = buffer.split('\n');
    buffer = lines.pop() ?? '';

    for (const line of lines) {
      const trimmed = line.trim();
      if (!trimmed) continue;

      lineCount++;
      let parsed: any;
      try { parsed = JSON.parse(trimmed); } catch { continue; }

      if (parsed.kind === 'text') {
        if (parsed.link_desc) {
          const prog = parseProgram(parsed.text || '', parsed.link_desc);
          programs.push(prog);
          if (parsed.text) aiText += parsed.text + '\n';
        } else if (parsed.text) {
          aiText += parsed.text;
        }
      } else if (parsed.kind === 'link') {
        if (parsed.label_key && parsed.link) {
          links[parsed.label_key] = parsed.link;
          const prog = programs.find(p => p.num === parsed.label_key);
          if (prog) prog.link = parsed.link;
        }
      } else if (parsed.kind === 'all') {
        allData = parsed;
        onProgress?.(`✅ 选校解析完成 | ID: ${parsed.select_program_id || parsed.id || '未知'}`);
      } else if (parsed.kind === 'loading') {
        onProgress?.(`⏳ ${parsed.message || parsed.text || '处理中...'}`);
      }
    }
  }

  if (buffer.trim()) {
    try {
      const parsed = JSON.parse(buffer.trim());
      if (parsed.kind === 'all') allData = parsed;
      else if (parsed.kind === 'text') {
        if (parsed.link_desc) {
          programs.push(parseProgram(parsed.text || '', parsed.link_desc));
        } else if (parsed.text) {
          aiText += parsed.text;
        }
      }
    } catch { }
  }

  // ── Fallback：如果 Xiaofang 没有返回 link_desc，从 aiText 解析编号列表 ──
  // 格式：「1、学校名 – 项目名，语言要求：TOEFL XX，...」
  if (programs.length === 0 && aiText.trim()) {
    // 非贪婪匹配 + lookahead：每个条目截止于下一个「数字、」或字符串尾
    // 加 's' flag 让 . 也能匹配换行（dotAll）
    const itemRe = /(\d+)[、.]\s*(.+?)(?=\s*\d+[、.]|$)/gs;
    let m: RegExpExecArray | null;
    while ((m = itemRe.exec(aiText)) !== null) {
      const num = m[1];
      const raw = m[2].trim();
      // 取第一个「，」「、」「\n」「 –」之前的内容作为学校+项目名
      const namePart = raw.split(/[，,\n]/)[0].split(' – ')[0].trim();
      if (namePart.length > 2 && namePart.length < 60) {
        const link = links[num] || undefined;
        programs.push({ num, name: namePart, tier: '稳', rawText: raw, link });
      }
    }
    if (programs.length > 0) {
      onProgress?.(`📋 从文本解析到 ${programs.length} 个项目（Fallback 模式）`);
    }
  }


  onProgress?.(`✅ 共收到 ${lineCount} 行数据，解析项目 ${programs.length} 个`);
  return { aiText, programs, links, allData, totalLines: lineCount };
}

