/**
 * 国际教育(collect + route)
 *   A. 选校选项目(select_program_recommend)—— collect 型:核对画像 → 采集背景 → 确认 → 执行 → 讨论
 *   B. 指定院校/项目的查询(program_deep_search / dash_search / search_internet)—— 直接路由
 */
import type { ModeSpec, PromptCtx, Slots } from '../types';
import * as F from '../fragments';
import { dashModelsLine } from '../toolspec';

const COUNTRIES = ['美国', '英国', '加拿大', '澳大利亚', '澳洲', '香港', '新加坡', '德国', '日本', '法国', '荷兰', '瑞士', '韩国', '新西兰', '爱尔兰', '中国香港', '澳门'];
const MAJOR_HINT = /(?:读|学|申请|申|转|去.{0,6}读)\s*([A-Za-z一-龥]{2,12}?)(?:专业|方向|硕士|博士|本科|研究生|的|，|,|。|$)/;

export function extractCountry(text: string): string | undefined {
  const hit = Array.from(new Set(COUNTRIES.filter(c => text.includes(c)).map(c => (c === '澳洲' ? '澳大利亚' : c))));
  return hit.length ? hit.join('|') : undefined;
}
export function extractDegree(text: string): string | undefined {
  if (/博士|phd/i.test(text)) return 'phd';
  if (/硕士|研究生|master|读研|\bms\b|msc/i.test(text)) return 'master';
  if (/本科|undergrad|bachelor/i.test(text)) return 'bachelor';
  return undefined;
}
export function extractGpa(text: string): string | undefined {
  const m = text.match(/GPA[^\d\n]{0,6}?([0-4]\.\d{1,2}|[0-4])(?![\d.])/i) || text.match(/(?:均分|平均分|绩点)\s*[:：是为]?\s*(\d{2}(?:\.\d)?|[0-4]\.\d{1,2})/);
  return m ? m[1] : undefined;
}
export function extractLanguage(text: string): string | undefined {
  let m = text.match(/(托福|toefl)\s*[:：]?\s*(\d{2,3})/i);
  if (m) return `toefl ${m[2]}`;
  m = text.match(/(雅思|ielts)\s*[:：]?\s*(\d(?:\.\d)?)/i);
  if (m) return `ielts ${m[2]}`;
  if (/(还没|没有|没)考(过)?(托福|雅思|语言)|语言.{0,4}(还没|没有)/.test(text)) return '未考';
  return undefined;
}
export function extractSchool(text: string): string | undefined {
  const m = text.match(/(?:我在|我是|就读于?|毕业于|来自|本科在?|在读于?)\s*([一-龥]{2,10}(?:大学|学院))/) || text.match(/([一-龥]{2,10}(?:大学|学院))\s*(?:毕业|在读|大[一二三四]|本科|读)/);
  return m ? m[1] : undefined;
}
export function extractMajor(text: string): string | undefined {
  const m = text.match(/(?:专业是|专业为|学的是|读的是|本科学|本科读)\s*([A-Za-z一-龥]{2,12})/);
  return m ? m[1] : undefined;
}
export function extractTargetMajor(text: string): string | undefined {
  let m = text.match(/(?<![A-Za-z])(CS|EE|ECE|DS|BA|MBA|MFin|MPA|LLM)(?![A-Za-z])/i);
  if (m) return m[1].toUpperCase();
  m = text.match(MAJOR_HINT);
  if (m && !['什么', '哪个', '哪些', '一个', '这个'].includes(m[1]) && !/校|没|变|什么|哪|专业/.test(m[1])) return m[1];
  return undefined;
}
export function extractGre(text: string): string | undefined {
  const m = text.match(/(GRE|GMAT)\s*[:：]?\s*(\d{3})/i);
  return m ? `${m[1].toLowerCase()} ${m[2]}` : undefined;
}

const LOOKUP_KW = /申请要求|截止|ddl|学费|费用|多少钱|排名|案例|怎么样|了解一下|介绍|课程|录取率|规划|时间线/i;
const RECOMMEND_KW = /推荐|选校|能去哪|能申|能上|适合我|帮我选|定位/;

export function bypassCollect(lastUser: string): boolean {
  if (RECOMMEND_KW.test(lastUser)) return false;
  return LOOKUP_KW.test(lastUser);
}
export function wantsMain(lastUser: string): boolean {
  const hasNum = !!(extractGpa(lastUser) || extractLanguage(lastUser));
  if (/是什么|什么意思|什么是|区别|要不要|值不值|该不该/.test(lastUser) && !hasNum) return false;
  if (RECOMMEND_KW.test(lastUser)) return true;
  return hasNum && !LOOKUP_KW.test(lastUser);
}
export function argsToSlots(a: Record<string, string>): Slots {
  const out: Slots = {};
  if (a.current_school) out.school = a.current_school;
  if (a.current_major) out.major = a.current_major;
  if (a.gpa && a.gpa !== '0') out.gpa = a.gpa;
  if (a.target_country) out.target_country = a.target_country;
  if (a.target_major) out.target_major = a.target_major;
  if (a.apply_degree) out.degree = a.apply_degree === 'graduate' ? 'master' : a.apply_degree === 'undergraduate' ? 'bachelor' : a.apply_degree;
  if (a.language_test_grade && a.language_test_grade !== '0') out.language = `${a.language_test_type || 'toefl'} ${a.language_test_grade}`;
  if (a.test_grade && a.test_grade !== '0') out.gre = `${a.test_type || 'gre'} ${a.test_grade}`;
  return out;
}
/** 槽位 → runSelectProgramRecommend 的参数(v2 现有执行器的口径) */
export function mainToolArgs(s: Slots): Record<string, unknown> {
  const lang = String(s.language || ''), gre = String(s.gre || '');
  const [lt, lg] = lang.startsWith('toefl') || lang.startsWith('ielts') ? lang.split(' ') : ['toefl', '0'];
  const [tt, tg] = gre ? gre.split(' ') : ['gre', '0'];
  const degree = s.degree === 'master' ? 'graduate' : s.degree === 'bachelor' ? 'undergraduate' : s.degree === 'phd' ? 'phd' : 'graduate';
  return { current_school: s.school, current_major: s.major, target_country: String(s.target_country || '').split('|')[0], target_major: s.target_major,
    gpa: parseFloat(String(s.gpa || '0')) || 0, apply_degree: degree, language_test_type: lt, language_test_grade: parseInt(lg || '0', 10) || 0,
    test_type: tt, test_grade: parseInt(tg || '0', 10) || 0 };
}

const LOOKUP_TOOLS = ['program_deep_search', 'dash_search', 'search_internet'];
const DISCUSS_MODELS = ['CRMInstitute', 'CRMProgram', 'CRMFos', 'CRMCase'];

function buildPrompt(ctx: PromptCtx): string {
  return [
    F.nowLine(ctx.today),
    `【模式身份:国际教育】
你是知己 Pro 的留学顾问,背后是平方的全球院校项目库和真实录取案例。你做两类事:
A. **选校选项目**:根据学生背景,调用选校引擎给出冲/稳/保方案(结果显示在右侧工具窗口)。
B. **定点查询**:某校某项目的申请要求、排名、录取案例、费用、深度项目报告。

【先判断用户要哪一类】
- "帮我推荐/选校/我这背景能去哪" → A
- "哈佛 CS 要求是什么 / UCL 金融怎么样 / 去英国读一年多少钱" → B,直接查,不要反过来盘问背景
- 拿不准就问一句:"你是想让我出一份选校方案,还是先了解某个具体学校/项目?"`,
    `【A 类的信息槽位】调用 select_program_recommend 前必须具备:
| 目标国家/地区 | 目标专业 | 申请学位 | 当前院校 | 当前专业 | GPA | 语言成绩(没考可填"未考"或预估) |
GRE/GMAT 选填,不追问。
追问顺序:目标(国家+专业)→ 学位 → 院校与专业 → GPA → 语言。

【B 类的工具选择】
- 想要一份"这个项目到底怎么样"的深度报告 → program_deep_search(一次一所学校一个方向;多所就并发多次)
- 院校/项目/专业/案例的结构化信息 → dash_search;费用、政策、最新动态 → search_internet`,
    F.ONE_QUESTION,
    F.toolManual(ctx.mode.tools),
    dashModelsLine(DISCUSS_MODELS),
    `【拿到结果之后】
- select_program_recommend:选校引擎的分析已原样发给用户,项目列表在右侧窗口。你只补 1–2 段:定位判断(这个背景在目标国家/专业里处于什么位置)+ 最值得先看的 2–3 个项目及理由 + 一个下一步("想深入看哪个项目?我可以做深度检索")。不要重排、不要重列。
- program_deep_search:报告已原样发给用户。你只补一句衔接和一个追问。
- 其余查询类:先给结论,再列数据,注明数据年份。`,
    F.DATA_TRUST,
  ].join('\n\n');
}

export const MODE: ModeSpec = {
  id: 'intl_edu', name: '国际教育', kind: 'collect', role: '全球留学选校与国际项目分析顾问',
  tools: ['select_program_recommend', ...LOOKUP_TOOLS],
  mainTool: 'select_program_recommend', mainToolArgs, requireAny: [],
  confirmBeforeRun: true, bypassCollect, wantsMain, argsToSlots, discussTools: [...LOOKUP_TOOLS, 'select_program_recommend'],
  slots: [
    { key: 'target_country', label: '目标国家/地区', required: true, askOrder: 1, extract: extractCountry, profileKeys: ['apply_country_cn', 'target_country'] },
    { key: 'target_major', label: '目标专业', required: true, askOrder: 1, askHint: '和目标国家可以一起问(算一个问题)', extract: extractTargetMajor, profileKeys: ['target_major'] },
    { key: 'degree', label: '申请学位', required: true, askOrder: 2, askHint: '硕士/本科/博士;用户说"读研"即硕士', extract: extractDegree, profileKeys: ['apply_degree', 'target_degree'] },
    { key: 'school', label: '当前院校', required: true, askOrder: 3, extract: extractSchool, profileKeys: ['graduation_institution', 'school'] },
    { key: 'major', label: '当前专业', required: true, askOrder: 3, askHint: '和当前院校一起问(算一个问题)', extract: extractMajor, profileKeys: ['major'] },
    { key: 'gpa', label: 'GPA/均分', required: true, askOrder: 4, askHint: '4.0 制或百分制都行;不确定可估', extract: extractGpa, profileKeys: ['gpa'] },
    { key: 'language', label: '语言成绩', required: true, askOrder: 5, askHint: '托福/雅思;没考过可以说"未考"或给预估', extract: extractLanguage, profileKeys: ['language', 'toefl', 'ielts'] },
    { key: 'gre', label: 'GRE/GMAT', required: false, askOrder: 9, extract: extractGre, profileKeys: ['gre'] },
  ],
  buildPrompt,
  synth: {
    select_program_recommend: '选校引擎的分析已原样发给用户,项目列表已在右侧窗口。现在只写 1–2 段定位判断 + 最值得先看的 2–3 个项目及理由 + 一个下一步。禁止重排或重列项目。',
    program_deep_search: '深度报告已原样发给用户。只补一句衔接 + 一个有针对性的追问,不要复述报告。',
    default: '基于工具返回的真实数据回答;先结论后数据;注明数据年份;不编造。',
  },
  followUps: {
    select_program_recommend: ['深入看看其中一个项目', '我的背景短板在哪,怎么补?', '换一个国家再推荐一次', '帮我排一下申请时间线'],
    program_deep_search: ['这个项目的录取案例', '和另一所学校的同类项目对比', '读下来总花费大概多少?'],
  },
