/** 项目行:SelectProgramItem + 25 版多出来的结构化字段(技术接数据时直接填这些字段,填了就不再从 rawText 里猜) */
export type ProgramRow = SelectProgramItem & Partial<{ school: string; program: string; degree: string; intake: string; rate: string; deadline: string; open: boolean; tuition: string; duration: string; qs: string; the: string; meta: string; req: { official: Req; case_avg: Req; rec_min: Req } }>;
interface Row { key: string; num: string; school: string; program: string; degree: string; intake: string; tier: string; rate: string; link?: string; deadline: string; open: boolean | null; tuition: string; duration: string; qs: string; the: string; meta: string; req: { official: Req; case_avg: Req; rec_min: Req } }
function toRow(p: ProgramRow, i: number): Row {
  const raw = p.rawText || '', name = p.name || raw.split('，')[0] || `项目 ${i + 1}`;
  const [school0, program0] = name.includes(' - ') ? name.split(' - ', 2) : name.includes('-') && !/\d-\d/.test(name) ? name.split('-', 2) : [name, ''];
  const degree = p.degree || (/Ph\.?D|博士/.test(raw + name) ? '博士' : /M\.?S\.?|M\.?A\.?|Master|硕士|研究生/.test(raw + name) ? '硕士' : '本科');
  const deadline = p.deadline || pick(raw, /截止(?:日期|时间)?[：:]\s*([0-9-/.]+)/);
  const blank: Req = { gpa: '-', lang: '-', test: '-' };
  const req = p.req || { official: { gpa: pick(raw, /GPA[^：:]*要求[：:]\s*([^，,]+)/) || '-', lang: pick(raw, /语言要求[：:]\s*([^，,]+)/) || '-', test: pick(raw, /(?:GRE|GMAT)[^：:]*要求[：:]\s*([^，,]+)/) || '-' }, case_avg: blank, rec_min: blank };
  return { key: p.num || String(i), num: p.num || String(i + 1), school: (p.school || school0).trim(), program: (p.program || program0).trim(), degree, intake: p.intake || '', tier: p.tier || '稳', rate: p.rate || pick(raw, /录取概率[：:]?\s*([\d.]+%?)/), link: p.link,
