 * Stage 2: 平方数据库检索 — CRMInstitute → CRMProgram 关联查询
 * Stage 3: 互联网检索 — Gemini → 阿里云 qwen-plus → Bocha 三级降级
 * Stage 4: AI 结构化输出 — 流式生成项目名称、学位、学费、申请条件 等
 */

import { mcpToolsDataPlatform } from '@/lib/mcp/generated-tools';

// ── 互联网检索：三级降级（Gemini → 阿里云 → Bocha）──────────────────────

async function searchInternet(
  cleanInstitute: string,
  cleanProgram: string,
  sendLog: (msg: string) => void,
): Promise<string> {
  const geminiKey = process.env.GEMINI_API_KEY;
  const dashscopeKey = process.env.DASHSCOPE_API_KEY;
  const baseUrl = process.env.DASHSCOPE_BASE_URL || 'https://dashscope.aliyuncs.com/compatible-mode/v1';
  const bochaKey = process.env.BOCHA_API_KEY;

  // ── 优先：Gemini Search Grounding ──────────────────────────────────────
  if (geminiKey) {
    sendLog('🚀 启动 Gemini Search Grounding...');
    try {
      const geminiQuery = `搜索"${cleanInstitute}"院校的"${cleanProgram}"相关项目(Program)信息，包括：项目介绍、学位要求、学费、申请条件、截止日期、官方申请链接。请用中文回答。`;
      const geminiRes = await fetch(
        `https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash:generateContent?key=${geminiKey}`,
        {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            contents: [{ role: 'user', parts: [{ text: geminiQuery }] }],
            tools: [{ googleSearch: {} }],
          }),
          signal: AbortSignal.timeout(30000),
        },
      );
      if (geminiRes.ok) {
        const geminiData = await geminiRes.json();
        const text = geminiData.candidates?.[0]?.content?.parts?.map((p: any) => p.text).join('') || '';
        if (text && text.length > 50) {
          sendLog('✅ Gemini 全网检索成功');
          return text;
        }
      }
    } catch (e) {
      sendLog(`⚠️ Gemini 检索失败: ${e}`);
    }
  }

  // ── 降级 1：阿里云 qwen-plus（enable_search）──────────────────────────
  if (dashscopeKey) {
    sendLog('🔄 降级使用阿里云大模型搜索...');
    try {
      const searchQuery = `${cleanInstitute} ${cleanProgram} 招生 项目 申请要求 学费 截止日期`;
      const res = await fetch(`${baseUrl}/chat/completions`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${dashscopeKey}` },
        body: JSON.stringify({
          model: 'qwen-plus',
          messages: [
            { role: 'system', content: '你是一个搜索助手，请根据用户的问题搜索相关信息并提供准确的答案。' },
            { role: 'user', content: searchQuery },
          ],
          enable_search: true,
        }),
        signal: AbortSignal.timeout(30000),
      });
      if (res.ok) {
        const data = await res.json();
        const content = data.choices?.[0]?.message?.content || '';
        if (content && content.length > 30) {
          sendLog('✅ 阿里云搜索获得补充信息');
          return content;
        }
      }
    } catch (e) {
      console.error('[ProgramDeepSearch] 阿里云搜索失败:', e);
    }
  }

  // ── 降级 2：Bocha ──────────────────────────────────────────────────────
  if (bochaKey) {
    sendLog('🔄 降级使用 Bocha 综合检索...');
    try {
      const res = await fetch('https://api.bochaai.com/v1/web-search', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${bochaKey}` },
        body: JSON.stringify({
          query: `${cleanInstitute} ${cleanProgram} 招生 项目 申请要求 学费`,
          freshness: 'noLimit',
          summary: true,
          count: 5,
        }),
        signal: AbortSignal.timeout(8000),
      });
      if (res.ok) {
        const data = await res.json();
        const results = data.data?.webPages?.value ?? [];
        if (results.length > 0) {
          const text = results
            .slice(0, 5)
            .map((r: any, i: number) => `${i + 1}. **${r.name}**\n   ${r.url}\n   ${r.snippet ?? ''}`)
            .join('\n\n');
          sendLog(`✅ Bocha 综合检索获得 ${results.length} 条补充信息`);
          return text;
        }
      }
    } catch (e) {
      console.error('[ProgramDeepSearch] Bocha 搜索失败:', e);
    }
  }

  return '';
}

